package net.civeira.phylax.features.document.snippet.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.features.document.snippet.domain.Snippet;

public interface SnippetCacheGateway {

  /**
   * @autogenerated CacheGatewayGenerator
   */
  void evict();

  /**
   * @autogenerated CacheGatewayGenerator
   * @param snippet
   */
  void remove(Snippet snippet);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param filter
   * @param cursor
   * @return
   */
  Optional<SnippetCached> retrieve(SnippetFilter filter, SnippetCursor cursor);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param filter
   * @param cursor
   * @param snippets
   * @return
   */
  SnippetCached store(SnippetFilter filter, SnippetCursor cursor, List<Snippet> snippets);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param snippet
   */
  void update(Snippet snippet);
}
